PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS menu_categories (id TEXT PRIMARY KEY,label TEXT NOT NULL,intro TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS menu_items (id TEXT PRIMARY KEY,category_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_kes INTEGER,variants_json TEXT NOT NULL DEFAULT '[]',image_url TEXT NOT NULL DEFAULT '',badge TEXT NOT NULL DEFAULT '',available INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES menu_categories(id));
CREATE TABLE IF NOT EXISTS staff_users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT NOT NULL,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'staff' CHECK(role IN('owner','manager','staff','kitchen')),is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS staff_sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES staff_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,fulfilment TEXT NOT NULL CHECK(fulfilment IN('delivery','collection')),delivery_address TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',subtotal_kes INTEGER NOT NULL,delivery_fee_kes INTEGER NOT NULL DEFAULT 0,total_kes INTEGER NOT NULL,payment_method TEXT NOT NULL DEFAULT 'cash',payment_status TEXT NOT NULL DEFAULT 'unpaid',is_demo INTEGER NOT NULL DEFAULT 1,accepted_by TEXT,rejection_reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,menu_item_id TEXT NOT NULL,item_name TEXT NOT NULL,variant TEXT NOT NULL DEFAULT '',unit_price_kes INTEGER NOT NULL,quantity INTEGER NOT NULL,line_total_kes INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS order_events (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,actor_name TEXT NOT NULL,from_status TEXT NOT NULL DEFAULT '',to_status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS mpesa_payments (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,merchant_request_id TEXT NOT NULL DEFAULT '',checkout_request_id TEXT NOT NULL UNIQUE,phone_number TEXT NOT NULL,amount_kes INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',mpesa_receipt_number TEXT NOT NULL DEFAULT '',result_code TEXT NOT NULL DEFAULT '',result_description TEXT NOT NULL DEFAULT '',callback_json TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS app_settings (setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO app_settings(setting_key,setting_value) VALUES('delivery_enabled','true'),('collection_enabled','true'),('store_open','true'),('delivery_fee_kes','0'),('minimum_order_kes','0'),('demo_mode','true');

CREATE INDEX IF NOT EXISTS idx_menu_items_category ON menu_items(category_id, sort_order);
CREATE INDEX IF NOT EXISTS idx_staff_sessions_expiry ON staff_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_orders_status_created ON orders(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_customer_phone ON orders(customer_phone);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_order_events_order ON order_events(order_id, created_at);
